// Package postgres stores the receivables module's data in PostgreSQL:
// credit accounts, receivables and customer payments, with the queries of
// queries/ generated by sqlc (sqlcgen).
package postgres

import (
	"context"
	"errors"
	"fmt"
	"math"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"github.com/brayangomez22/cuadra-app/backend/internal/modules/receivables/adapters/postgres/sqlcgen"
	"github.com/brayangomez22/cuadra-app/backend/internal/modules/receivables/domain"
	"github.com/brayangomez22/cuadra-app/backend/internal/platform/db"
)

// errNoAccount means a credit operation changed an account that does not
// exist: the domain never lets that happen.
var errNoAccount = errors.New("receivables: change of a customer without credit account")

// accountCustomerFKey is the account's foreign key to customers.
const accountCustomerFKey = "credit_accounts_customer_fkey"

// CreditRepository implements domain.CreditRepository.
type CreditRepository struct {
	db *db.DB
}

// NewCreditRepository returns a CreditRepository on d.
func NewCreditRepository(d *db.DB) *CreditRepository { return &CreditRepository{db: d} }

// Account returns the customer's account, or a new one with zero terms if
// it has none.
func (r *CreditRepository) Account(ctx context.Context, tenantID, customerID uuid.UUID) (*domain.Account, error) {
	row, err := db.Read(ctx, r.db, tenantID, func(tx pgx.Tx) (sqlcgen.CreditAccount, error) {
		return sqlcgen.New(tx).GetCreditAccount(ctx, customerID)
	})
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		return noAccount(tenantID, customerID), nil
	case err != nil:
		return nil, fmt.Errorf("receivables: get account: %w", err)
	}
	return accountOf(row), nil
}

// SaveTerms stores the account's limit and term, creating the account with
// a zero balance if needed.
func (r *CreditRepository) SaveTerms(ctx context.Context, a *domain.Account, at time.Time) error {
	days, err := termDays(a.Terms().Days())
	if err != nil {
		return err
	}
	err = r.db.WithTenantTx(ctx, a.TenantID(), func(tx pgx.Tx) error {
		return sqlcgen.New(tx).UpsertCreditTerms(ctx, sqlcgen.UpsertCreditTermsParams{
			TenantID: a.TenantID(), CustomerID: a.CustomerID(), CreditLimit: a.Terms().Limit(),
			TermDays: days, UpdatedAt: at,
		})
	})
	switch {
	case db.Violates(err, db.ForeignKeyViolation, accountCustomerFKey):
		return domain.ErrCustomerNotFound
	case err != nil:
		return fmt.Errorf("receivables: save terms: %w", err)
	}
	return nil
}

// termDays converts a term to its column; the domain keeps it within 0–365.
func termDays(days int) (int32, error) {
	if days < 0 || days > math.MaxInt32 {
		return 0, domain.ErrInvalidCreditTerm
	}
	return int32(days), nil
}

// Update runs a credit operation on the customer's account:
//
//  1. locks the account (FOR UPDATE), joining ctx's transaction if any, so
//     the operations of a customer run one at a time until it commits;
//  2. reads its open receivables and calls fn with both;
//  3. stores the account's new balance and what fn changed.
//
// fn's errors come back as they are; if anything fails, nothing is stored.
func (r *CreditRepository) Update(ctx context.Context, tenantID, customerID uuid.UUID,
	fn func(context.Context, *domain.Account, []*domain.Receivable) (domain.Change, error),
) error {
	var fnErr error
	err := r.db.InTenantTx(ctx, tenantID, func(ctx context.Context, tx pgx.Tx) error {
		q := sqlcgen.New(tx)
		account, exists, err := lockAccount(ctx, q, tenantID, customerID)
		if err != nil {
			return err
		}
		open, err := q.OpenReceivables(ctx, customerID)
		if err != nil {
			return err
		}
		change, err := fn(ctx, account, receivablesOf(open))
		if err != nil {
			fnErr = err
			return err
		}
		if !exists {
			return errNoAccount
		}
		return storeChange(ctx, q, account, change)
	})
	switch {
	case fnErr != nil:
		return fnErr
	case err != nil:
		return fmt.Errorf("receivables: update account of %s: %w", customerID, err)
	}
	return nil
}

// lockAccount locks and returns the customer's account; without one, a new
// account with zero terms and exists false.
func lockAccount(ctx context.Context, q *sqlcgen.Queries, tenantID, customerID uuid.UUID) (_ *domain.Account, exists bool, _ error) {
	row, err := q.LockCreditAccount(ctx, customerID)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		return noAccount(tenantID, customerID), false, nil
	case err != nil:
		return nil, false, err
	}
	return accountOf(row), true, nil
}

// storeChange writes the account's balance, the receivable opened, the
// receivables changed and the payment received.
func storeChange(ctx context.Context, q *sqlcgen.Queries, a *domain.Account, c domain.Change) error {
	if err := q.SetCreditBalance(ctx, sqlcgen.SetCreditBalanceParams{CustomerID: a.CustomerID(), Balance: a.Balance()}); err != nil {
		return err
	}
	if c.Opened != nil {
		if err := insertReceivable(ctx, q, c.Opened.Snapshot()); err != nil {
			return err
		}
	}
	for _, r := range c.Changed {
		s := r.Snapshot()
		if err := q.UpdateReceivable(ctx, sqlcgen.UpdateReceivableParams{
			ID: s.ID, Balance: s.Balance, Status: string(s.Status), CanceledAt: s.CanceledAt,
		}); err != nil {
			return err
		}
	}
	if c.Payment != nil {
		return insertPayment(ctx, q, *c.Payment)
	}
	return nil
}

func insertReceivable(ctx context.Context, q *sqlcgen.Queries, s domain.ReceivableSnapshot) error {
	p := sqlcgen.InsertReceivableParams{
		ID: s.ID, TenantID: s.TenantID, CustomerID: s.CustomerID, SaleID: s.SaleID, Amount: s.Amount,
		Balance: s.Balance, DueDate: s.DueDate.Time(), Status: string(s.Status), CreatedAt: s.CreatedAt,
	}
	if s.Authorization != nil {
		p.AuthorizedBy, p.AuthorizedAt = &s.Authorization.UserID, &s.Authorization.At
	}
	return q.InsertReceivable(ctx, p)
}

func insertPayment(ctx context.Context, q *sqlcgen.Queries, p domain.Payment) error {
	if err := q.InsertCustomerPayment(ctx, sqlcgen.InsertCustomerPaymentParams{
		ID: p.ID(), TenantID: p.TenantID(), CustomerID: p.CustomerID(), Method: p.Method().String(),
		Amount: p.Amount(), UserID: p.UserID(), CashSessionID: p.CashSessionID(), CreatedAt: p.CreatedAt(),
	}); err != nil {
		return err
	}
	allocations := p.Allocations()
	if len(allocations) > math.MaxInt32 {
		return errors.New("too many allocations")
	}
	for i, a := range allocations {
		if err := q.InsertPaymentAllocation(ctx, sqlcgen.InsertPaymentAllocationParams{
			TenantID: p.TenantID(), PaymentID: p.ID(), ReceivableID: a.ReceivableID, Position: int32(i), Amount: a.Amount,
		}); err != nil {
			return err
		}
	}
	return nil
}
